package collect

import (
	"github.com/hashicorp/hcl/v2"
	"github.com/hashicorp/hcl/v2/hclsyntax"
)

// Dynamic blocks.
//
// Terraform's JSON plan does not describe a dynamic block. The configuration it
// carries lists a resource's attributes and its statically written nested
// blocks; a block generated by `dynamic "route" { ... }` is simply not there, so
// nothing the block reads is reported either. Registry modules generate most of
// their nested blocks this way — security group rules, routes, launch template
// network interfaces — so those resources lose exactly the links a diagram
// draws.
//
// The .tf files do say, and the collector already reads them for locals. What
// it takes from a dynamic block is the same narrow thing: the names its
// for_each and its content refer to. No value, no literal, no block content.
//
// A dynamic block's content mostly reads the iterator, not a resource:
//
//	dynamic "ingress" {
//	  for_each = var.ingress_rules
//	  content { security_groups = ingress.value.security_groups }
//	}
//
// `ingress.value` names nothing. What it draws from is the for_each one line
// up, so the iterator is replaced by what the for_each references, exactly as
// iterationRefs does for `each`. As there, the link is to the whole collection:
// which element a generated block takes is not knowable from the configuration.
//
// References are reported in the shape the plan uses for a written block, so
// the renderer needs no second code path: BlockType is the outermost block
// under the resource, Via the attribute read, or the nested block it sits in.
// BlockIndex is 0: a dynamic block is one description of however many blocks
// its collection generates, and every one of them makes the same references.

// iterationScope maps an iterator name to what its collection references.
// `each` is one of them when the resource itself iterates.
type iterationScope map[string][]string

func (scope iterationScope) with(name string, refs []string) iterationScope {
	inner := make(iterationScope, len(scope)+1)
	for key, value := range scope {
		inner[key] = value
	}
	inner[name] = refs
	return inner
}

// scanDynamicBlocks reads what the dynamic blocks of every resource and data
// source in one module directory refer to.
func (s *symbolScanner) scanDynamicBlocks(modulePath, modulePrefix string) {
	forEachTerraformBody(modulePath, func(body *hclsyntax.Body) {
		for _, block := range body.Blocks {
			source := blockSource(modulePrefix, block)
			if source == "" {
				continue
			}
			scope := iterationScope{}
			if forEach := block.Body.Attributes["for_each"]; forEach != nil {
				scope = scope.with("each", scopedRefs(modulePrefix, forEach.Expr, scope))
			}
			s.findDynamicBlocks(source, modulePrefix, block.Body, "", scope)
		}
	})
}

// blockSource is the address a resource or data block is referred to by, or ""
// for any other block.
func blockSource(modulePrefix string, block *hclsyntax.Block) string {
	if len(block.Labels) != 2 {
		return ""
	}
	switch block.Type {
	case "resource":
		return qualifyRef(modulePrefix, block.Labels)
	case "data":
		return qualifyRef(modulePrefix, []string{"data", block.Labels[0], block.Labels[1]})
	}
	return ""
}

// findDynamicBlocks walks a body's written blocks looking for dynamic ones.
// outer is the outermost written block the walk is inside, "" at the top of the
// resource. Written blocks are only walked through: the plan already reports
// what they read.
func (s *symbolScanner) findDynamicBlocks(source, modulePrefix string, body *hclsyntax.Body, outer string, scope iterationScope) {
	for _, block := range body.Blocks {
		if name, inner, ok := dynamicBlock(modulePrefix, block, scope); ok {
			blockType, via := outer, name
			if outer == "" {
				blockType, via = name, ""
			}
			s.emitDynamicContent(source, modulePrefix, block.Body, blockType, via, inner)
			continue
		}
		blockType := outer
		if blockType == "" {
			blockType = block.Type
		}
		s.findDynamicBlocks(source, modulePrefix, block.Body, blockType, scope)
	}
}

// dynamicBlock reports the name of the block a dynamic block generates and the
// scope its content is read in. ok is false for any other block.
func dynamicBlock(modulePrefix string, block *hclsyntax.Block, scope iterationScope) (name string, inner iterationScope, ok bool) {
	if block.Type != "dynamic" || len(block.Labels) != 1 {
		return "", nil, false
	}
	name = block.Labels[0]
	iterator := name
	if attribute := block.Body.Attributes["iterator"]; attribute != nil {
		if keyword := hcl.ExprAsKeyword(attribute.Expr); keyword != "" {
			iterator = keyword
		}
	}
	var collection []string
	if forEach := block.Body.Attributes["for_each"]; forEach != nil {
		collection = scopedRefs(modulePrefix, forEach.Expr, scope)
	}
	return name, scope.with(iterator, collection), true
}

// emitDynamicContent records what the content of a dynamic block reads. body is
// the dynamic block's own body; via is "" until the walk is inside a nested
// block, whose name then stands for every attribute beneath it.
func (s *symbolScanner) emitDynamicContent(source, modulePrefix string, body *hclsyntax.Body, blockType, via string, scope iterationScope) {
	for _, block := range body.Blocks {
		if block.Type == "content" {
			s.emitBlockBody(source, modulePrefix, block.Body, blockType, via, scope)
		}
	}
}

func (s *symbolScanner) emitBlockBody(source, modulePrefix string, body *hclsyntax.Body, blockType, via string, scope iterationScope) {
	for name, attribute := range body.Attributes {
		attributeVia := via
		if attributeVia == "" {
			attributeVia = name
		}
		for _, ref := range scopedRefs(modulePrefix, attribute.Expr, scope) {
			if ref == source {
				continue
			}
			s.references[Reference{
				Source: source, Via: attributeVia, BlockType: blockType, Ref: ref,
			}] = true
		}
	}
	for _, block := range body.Blocks {
		if name, inner, ok := dynamicBlock(modulePrefix, block, scope); ok {
			nestedVia := via
			if nestedVia == "" {
				nestedVia = name
			}
			s.emitDynamicContent(source, modulePrefix, block.Body, blockType, nestedVia, inner)
			continue
		}
		nestedVia := via
		if nestedVia == "" {
			nestedVia = block.Type
		}
		s.emitBlockBody(source, modulePrefix, block.Body, blockType, nestedVia, scope)
	}
}

// scopedRefs reports what an expression names, with every iterator in scope
// replaced by what its collection references.
func scopedRefs(modulePrefix string, expr hcl.Expression, scope iterationScope) []string {
	if expr == nil {
		return nil
	}
	var refs []string
	for _, traversal := range expr.Variables() {
		if collection, iterates := scope[traversal.RootName()]; iterates {
			refs = appendUnique(refs, collection...)
			continue
		}
		if ref := traversalRef(modulePrefix, traversal); ref != "" {
			refs = appendUnique(refs, ref)
		}
	}
	return refs
}
